    """Remove dot segments and percent-normalize a raw (still encoded) path.

    Segments are split on literal '/'; a percent-encoded slash (%2F) stays
    inside its segment. A segment is a dot segment when it is "." / ".." or
    an ASCII-case-insensitive percent-encoding of one (matching how browser
    URL parsers treat it); other segments are decoded and re-encoded.
    """
    dot_forms = {".", ".."}
    for lower in ("%2e", "%2e%2e"):
        for mask in range(4):
            dot_forms.add(
                "".join(
                    part.upper() if mask >> index & 1 else part
                    for index, part in enumerate((lower[:3], lower[3:]))
